package com.sunmo.stockplatform.kis.websocket;
import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.*;
class KisRealtimeTickParserTest {
 @Test void mapsOfficialRealtimeTradeFieldPositions(){String[] fields=new String[46];java.util.Arrays.fill(fields,"0");fields[0]="005930";fields[1]="091501";fields[2]="72000";fields[7]="71000";fields[8]="73000";fields[9]="70000";fields[12]="15";fields[13]="123456";fields[14]="8888832000";fields[18]="132.45";fields[19]="45678";fields[20]="54321";fields[22]="54.3";fields[35]="Y";fields[40]="0.82";fields[45]="75000";var tick=new KisRealtimeTickParser().parse(String.join("^",fields));assertThat(tick.stockCode()).isEqualTo("005930");assertThat(tick.price()).isEqualByComparingTo("72000");assertThat(tick.tradeVolume()).isEqualTo(15);assertThat(tick.cumulativeVolume()).isEqualTo(123456);assertThat(tick.openPrice()).isEqualByComparingTo("71000");assertThat(tick.highPrice()).isEqualByComparingTo("73000");assertThat(tick.lowPrice()).isEqualByComparingTo("70000");assertThat(tick.tradeStrength()).isEqualByComparingTo("132.45");assertThat(tick.cumulativeSellVolume()).isEqualTo(45678);assertThat(tick.cumulativeBuyVolume()).isEqualTo(54321);assertThat(tick.buyRatio()).isEqualByComparingTo("54.3");assertThat(tick.tradingHalted()).isTrue();assertThat(tick.viStandardPrice()).isEqualByComparingTo("75000");assertThat(tick.turnoverRate()).isEqualByComparingTo("0.82");}
}
